begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a2060000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mode206@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2060000-0000-4000-8000-000000000001','Mode206','Mode206','ACTIVE','a2060000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c2060000-0000-4000-8000-000000000001','b2060000-0000-4000-8000-000000000001','a2060000-0000-4000-8000-000000000001','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c2060000-0000-4000-8000-000000000001','CLIENT_OWNER');
-- A real minimal catalogue hierarchy supports FK checks on every subsequent edit.
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by)values('d2060000-0000-4000-9000-000000000001','MODE206','mode206','b2060000-0000-4000-8000-000000000001','a2060000-0000-4000-8000-000000000001');
insert into public.catalog_categories(id,library_id,code,slug,created_by)values('d2060000-0000-4000-9000-000000000003','d2060000-0000-4000-9000-000000000001','MODE206_CAT','mode206-cat','a2060000-0000-4000-8000-000000000001');
insert into public.catalog_subcategories(id,library_id,category_id,code,slug,created_by)values('d2060000-0000-4000-9000-000000000004','d2060000-0000-4000-9000-000000000001','d2060000-0000-4000-9000-000000000003','MODE206_SUB','mode206-sub','a2060000-0000-4000-8000-000000000001');
insert into public.catalog_services(id,library_id,primary_subcategory_id,code,slug,created_by)values('d2060000-0000-4000-9000-000000000002','d2060000-0000-4000-9000-000000000001','d2060000-0000-4000-9000-000000000004','MODE206_SVC','mode206-svc','a2060000-0000-4000-8000-000000000001');
-- Historical published service source and the cyclic initial request/version link
-- are supplied as declared preconditions; no fiscal mapping is seeded.
set local session_replication_role=replica;
insert into public.catalog_service_versions(id,service_id,library_id,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,sort_order,change_reason,content_hash,created_by,published_at,primary_subcategory_id,code,slug)values('d2060000-0000-4000-9000-000000000005','d2060000-0000-4000-9000-000000000002','d2060000-0000-4000-9000-000000000001',1,'PUBLISHED','Service de mode206','خدمة طريقة206','Référence historique locale','مرجع تاريخي محلي','Précondition publiée de recette locale','شرط منشور للاختبار المحلي','CONSULTING','mission','مهمة',1,'Source historique de recette206',repeat('a',64),'a2060000-0000-4000-8000-000000000001',now()-interval'1 day','d2060000-0000-4000-9000-000000000004','MODE206_SVC','mode206-svc');
update public.catalog_services set status='PUBLISHED',current_published_version_id='d2060000-0000-4000-9000-000000000005'where id='d2060000-0000-4000-9000-000000000002';
insert into public.service_requests(id,client_organization_id,library_id,service_id,current_version_id,status,created_by)values('d2060000-0000-4000-8000-000000000001','b2060000-0000-4000-8000-000000000001','d2060000-0000-4000-9000-000000000001','d2060000-0000-4000-9000-000000000002','e2060000-0000-4000-8000-000000000001','DRAFT','a2060000-0000-4000-8000-000000000001');
insert into public.service_request_versions(id,request_id,client_organization_id,library_id,version_number,description,urgency,required_quote_data,catalog_snapshot_hash,questionnaire_snapshot_hash,change_reason,content_hash,created_by)values('e2060000-0000-4000-8000-000000000001','d2060000-0000-4000-8000-000000000001','b2060000-0000-4000-8000-000000000001','d2060000-0000-4000-9000-000000000001',1,'Besoin pour recette du mode','NORMAL','{}',repeat('a',64),repeat('a',64),'Source de recette',repeat('a',64),'a2060000-0000-4000-8000-000000000001');
set local session_replication_role=origin;
select set_config('request.jwt.claims','{"sub":"a2060000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',null,'{"intervention_mode":"ONSITE"}','CASABLANCA_SETTAT','null-version-206')$$,'40001','STALE_REQUEST_VERSION','NULL optimistic version never bypasses concurrency');
select throws_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',1,'{"intervention_mode":"Sur site"}','CASABLANCA_SETTAT','bad-mode-206')$$,'22023','INVALID_INTERVENTION_MODE','localized or invented modes are rejected');
select throws_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',1,'{"intervention_mode":null}','CASABLANCA_SETTAT','null-mode-206')$$,'22023','INVALID_INTERVENTION_MODE','JSON null cannot choose a mode');
select lives_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',1,'{"intervention_mode":"REMOTE"}','CASABLANCA_SETTAT','set-mode-206')$$,'Client chooses a canonical mode through the real versioned command');
select is((select v.required_quote_data->>'intervention_mode'from public.service_requests r join public.service_request_versions v on v.id=r.current_version_id where r.id='d2060000-0000-4000-8000-000000000001'),'REMOTE','matching reads the same immutable canonical mode');
select is((public.get_service_request_quote_questions('d2060000-0000-4000-8000-000000000001')->>'intervention_mode'),'REMOTE','reader returns the stored mode for the next edit');
select lives_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',1,'{"intervention_mode":"REMOTE"}','CASABLANCA_SETTAT','set-mode-206')$$,'same command replay succeeds without a duplicate version');
select lives_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',2,'{}','','preserve-mode-206')$$,'older callers that omit the optional key preserve the selected mode');
select is((select v.required_quote_data->>'intervention_mode'from public.service_requests r join public.service_request_versions v on v.id=r.current_version_id where r.id='d2060000-0000-4000-8000-000000000001'),'REMOTE','absence is never inferred as a different mode');
select lives_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',3,'{"intervention_mode":"HYBRID"}','','hybrid-mode-206')$$,'hybrid is a distinct canonical value');
select lives_ok($$select public.complete_service_request_information('d2060000-0000-4000-8000-000000000001',4,'{"intervention_mode":""}','','clear-mode-206')$$,'Client may explicitly leave mode unspecified');
select ok((select not(v.required_quote_data?'intervention_mode')from public.service_requests r join public.service_request_versions v on v.id=r.current_version_id where r.id='d2060000-0000-4000-8000-000000000001'),'clearing a mode leaves no fabricated default');
select is((select count(*)::integer from public.service_request_versions where request_id='d2060000-0000-4000-8000-000000000001'),5,'every material edit appends one frozen version');
select is((select required_quote_data from public.service_request_versions where id='e2060000-0000-4000-8000-000000000001'),'{}'::jsonb,'the original request version stays unchanged');
select * from finish();
rollback;
